/**
 * Memento Advisor: which mementos to suggest, and their rank (pure module, no engine globals).
 *
 * The scores are precomputed per leader + civilization (data/mma-table.js, generated by
 * tools/memento-advisor/build_table.py; method in research/16-memento-scoring.md): for each
 * ranking (Balanced and one per victory) the best 6 mementos, then 6 spares. Here the shown
 * ranking is picked (Auto = the pair's own victory) and the mementos the player cannot equip are
 * skipped, the spares filling in.
 */

export const MODES = ["AUTO", "BALANCED", "CULTURE", "SCIENCE", "ECONOMIC", "MILITARY"];
export const SHOWN = 6;

/** The ranking a mode shows: Auto = the pair's own victory (picks.focus), else the mode itself. */
export function rankingOf(mode, picks) {
    if (mode === "AUTO" || !MODES.includes(mode)) return picks?.focus ?? "BALANCED";
    return mode;
}

/**
 * What the player can equip, corrected by the cards the screen shows (`seen`: Map type -> locked).
 * The screen has the last word: Mattifus's Memento Editor can unlock every memento while the
 * game's data still calls them locked. null (no memento data) stays null: everything counts.
 */
export function equippable(available, seen) {
    if (!available) return null;
    const out = new Set(available);
    for (const [type, locked] of seen ?? []) {
        if (locked) out.delete(type);
        else out.add(type);
    }
    return out;
}

/**
 * Memento type -> rank 1..SHOWN for this ranking: its list, then its spares, skipping mementos
 * not in `available` (a Set of types the player can equip; null = all).
 * @returns Map
 */
export function rankMementos(picks, mode, available = null) {
    const key = rankingOf(mode, picks);
    const out = new Map();
    for (const type of [...(picks?.ranks?.[key] ?? []), ...(picks?.more?.[key] ?? [])]) {
        if (out.size >= SHOWN) break;
        if (out.has(type) || (available && !available.has(type))) continue;
        out.set(type, out.size + 1);
    }
    return out;
}
